import ast; import sys; from dataclasses import is_dataclass; from pathlib import Path; from typing import get_type_hints; from common.meta.extension.check_package_contract import check_single_package, discover_packages; REPO = Path(__file__).resolve().parents[2]; PLATFORM = REPO / 'apps/backend/src/platform'; _BACKEND_ROOT = str(REPO / 'apps' / 'backend'); sys.path.insert(0, _BACKEND_ROOT) if _BACKEND_ROOT not in sys.path else None
def _imported_modules(path: Path) -> set[str]: mods: set[str] = set(); [mods.add(node.module) if isinstance(node, ast.ImportFrom) and node.module else mods.update((a.name for a in node.names)) if isinstance(node, ast.Import) else None for node in ast.walk(ast.parse(path.read_text(encoding='utf-8')))]; return mods
def test_platform_converges_by_layer():
    assert (PLATFORM / 'base/event.py').exists(); assert (PLATFORM / 'base/bus.py').exists(); assert (PLATFORM / 'base/outbox.py').exists(); assert (PLATFORM / 'extension/bus.py').exists(); assert (PLATFORM / 'extension/relay.py').exists(); assert (PLATFORM / 'extension/sql.py').exists(); assert not (PLATFORM / 'events').exists(); assert not (PLATFORM / 'store').exists(); exports = (PLATFORM / '__init__.py').read_text(encoding='utf-8')
    for name in ('DomainEvent', 'EventBus', 'Outbox', 'OutboxEventBus', 'OutboxRelay'): assert name in exports, f'platform must export {name}'
def test_platform_repository_split(): assert (PLATFORM / 'base/outbox.py').exists(); assert (PLATFORM / 'extension/sql.py').exists(); assert (PLATFORM / 'base/bus.py').exists(); assert (PLATFORM / 'extension/bus.py').exists(); sql = (PLATFORM / 'extension/sql.py').read_text(encoding='utf-8'); assert 'class SqlOutboxRepository' in sql; ext_bus = (PLATFORM / 'extension/bus.py').read_text(encoding='utf-8'); assert 'class OutboxEventBus' in ext_bus
def test_AC_platform_boundary_1_outbox_public_language_is_not_an_orm_row(): 'AC-platform.boundary.1'; from src.platform import Outbox; from src.platform.extension.sql import OutboxRecord; assert is_dataclass(Outbox); assert Outbox is not OutboxRecord; assert Outbox.__module__ == 'src.platform.base.outbox'; from src.platform.base.outbox import OutboxRow; _m1_annotations = get_type_hints(OutboxRow); assert {'status', 'published_at'} <= _m1_annotations.keys()
def test_platform_base_layer_is_pure():
    offenders: dict[str, set[str]] = {}
    for path in sorted((PLATFORM / 'base').rglob('*.py')):
        bad = {m for m in _imported_modules(path) if m.startswith('src.platform.extension') or m == 'src.platform' or 'sqlalchemy' in m or (m == 'src.database')}
        if bad: offenders[str(path.relative_to(PLATFORM))] = bad
    assert not offenders, f'platform base/ reaches into extension/ORM: {offenders}'
def test_platform_interface_equals_published_language(): import src.platform as platform_pkg; from common.platform.contract import CONTRACT; assert sorted(CONTRACT.interface) == sorted(platform_pkg.__all__); assert CONTRACT.name == 'platform'; assert CONTRACT.klass == 'infra'; assert CONTRACT.implementations['be'] == 'apps/backend/src/platform'
def test_platform_package_contract_gate_passes(): names = {p.name for p in discover_packages(REPO)}; assert 'platform' in names, f'platform not discovered; found {names}'; ok, messages = check_single_package('platform', REPO); assert ok, 'package contract gate failed:\n' + '\n'.join(messages)
